/**
 * Stored `facts_json` shapes for the Evidence Basis rule tests: the three
 * packages captured from the live workspace endpoint (dispute #368528 and two
 * decided ones; `capturedPackages.json`) and one synthetic package per reason
 * family, plus a package of facts that must never be cited.
 *
 * Pure data and one builder: no imports from the app, so the same file feeds the
 * legacy golden (generated by the pre-change code) and the new-rule tests.
 */

import captured from "./capturedPackages.json";

export interface ShapeFact {
  id: string;
  category: string;
  label: string;
  value: Record<string, unknown>;
  source: string;
  sourceRef: string | null;
  strength: "strong" | "moderate" | "supporting";
  bankEligible: boolean;
  merchantVisible: boolean;
  internalOnly: boolean;
  includeInBankNarrative: boolean;
  submissionRisk: boolean;
  confidence: number | null;
}

export interface Shape {
  name: string;
  family: "fraud" | "not_received" | "credit_not_processed" | "not_as_described" | "subscription" | "adverse";
  facts: ShapeFact[];
  /** The evidence lines the live workspace would hold for this package. */
  lines: Array<{ field: string; hasEvidence: boolean; submissionMethod: string; strengthContribution: string }>;
}

let seq = 0;
function fact(
  category: string,
  fieldKey: string,
  label: string,
  strength: ShapeFact["strength"],
  value: Record<string, unknown>,
  flags: Partial<Pick<ShapeFact, "bankEligible" | "includeInBankNarrative" | "submissionRisk">> = {},
): ShapeFact {
  seq += 1;
  const bankEligible = flags.bankEligible ?? true;
  return {
    id: `${fieldKey}#${seq}`,
    category,
    label,
    value: { ...value, fieldKey },
    source: "shopify_order",
    sourceRef: null,
    strength,
    bankEligible,
    merchantVisible: true,
    internalOnly: false,
    includeInBankNarrative: flags.includeInBankNarrative ?? bankEligible,
    submissionRisk: flags.submissionRisk ?? false,
    confidence: null,
  };
}

const DELIVERED = {
  carrier: "Northwind Express",
  proofType: "delivered_confirmed",
  deliveredAt: "2026-10-25T19:33:59Z",
  trackingNumber: "TRK12345",
  trackingUrl: "https://example.test/t/TRK12345",
  signedByName: null,
};
const delivery = (v: Record<string, unknown> = DELIVERED, strength: ShapeFact["strength"] = "moderate") => [
  fact("shipping_tracking", "shipping_tracking", "Shipping tracking", strength, v),
  fact("delivery_proof", "delivery_proof", "Delivery confirmation", strength, v),
];
const order = () => fact("order_record", "order_confirmation", "Order record", "supporting", { channel: "web", fulfillmentStatus: "FULFILLED" });
const policy = (kind: "refund" | "shipping") =>
  fact(`policy_${kind}`, `${kind}_policy`, `${kind === "refund" ? "Refund" : "Shipping"} policy`, "supporting", { publishedOnStore: true });
const noReturn = () =>
  fact("no_return_initiated", "no_return_initiated", "No return recorded in Shopify", "moderate", { returnInitiated: false, returnStatus: "NO_RETURN" });
const history = () =>
  fact("prior_customer_history", "customer_account_info", "Customer account history", "strong", { priorOrderCount: 3, disputeFreeHistory: true });
const comms = () =>
  fact("customer_communication", "customer_communication", "Customer communication", "strong", { customerConfirmsOrder: true, lastMessageAt: "2026-10-20T10:00:00Z" });
const screening = () =>
  fact("fraud_screening", "fraud_risk_screening", "Pre-authorization fraud screening", "moderate", {
    recommendation: "ACCEPT",
    riskLevel: "LOW",
    positiveFacts: ["Characteristics of this order are similar to non-fraudulent orders observed in the past"],
  });
const ip = () => fact("ip_location", "ip_location_check", "IP & location consistency", "moderate", { locationMatch: "same_country" });
const payment = () =>
  fact("payment_authentication", "avs_cvv_match", "Payment authentication", "strong", {
    network: "visa",
    avsResultCode: "Y",
    cvvResultCode: "M",
    verificationSummary:
      "the billing address matched the issuer's records and the card verification code matched the issuer's records",
  });

function lineFor(f: ShapeFact): Shape["lines"][number] {
  const cited = f.bankEligible && f.includeInBankNarrative && !f.submissionRisk;
  // The live workspace has one line per record: the delivery pair is one line,
  // and the account history rides on the activity-log line.
  const key = f.value.fieldKey as string;
  const field = f.category === "delivery_proof" ? "shipping_tracking" : key === "customer_account_info" ? "activity_log" : key;
  return {
    field,
    hasEvidence: true,
    submissionMethod: cited ? (f.strength === "supporting" ? "context_only" : "bank_argument") : "internal_only",
    strengthContribution: f.strength,
  };
}

function shape(name: string, family: Shape["family"], facts: ShapeFact[]): Shape {
  const seen = new Set<string>();
  const lines = facts.map(lineFor).filter((l) => (seen.has(l.field) ? false : (seen.add(l.field), true)));
  return { name, family, facts, lines };
}

const capturedShape = (key: keyof typeof captured, family: Shape["family"]): Shape => ({
  name: `captured:${key}`,
  family,
  facts: captured[key].facts as unknown as ShapeFact[],
  lines: captured[key].lines as Shape["lines"],
});

const twoParcels = {
  ...DELIVERED,
  shipments: [
    { carrier: "GOFO", reference: "GF1", referenceIsTrackingNumber: true, proofType: "in_transit", fulfilledAt: "2026-10-16T10:00:00Z", items: [{ title: "Bundle", quantity: 1 }] },
    { carrier: "USPS", reference: "US1", referenceIsTrackingNumber: true, proofType: "delivered_confirmed", deliveredAt: "2026-10-22T10:00:00Z", fulfilledAt: "2026-10-17T10:00:00Z", items: [{ title: "Sunscreen", quantity: 1 }] },
  ],
};

export const SHAPES: Shape[] = [
  capturedShape("open_368528_v1", "fraud"),
  capturedShape("decided_v11", "fraud"),
  capturedShape("decided_v5_legacy_flags", "fraud"),
  shape("fraud_clean", "fraud", [payment(), screening(), ip(), ...delivery(), noReturn(), order(), history(), policy("refund")]),
  shape("not_received_delivered", "not_received", [...delivery(), order(), policy("shipping"), policy("refund"), history(), comms()]),
  shape("not_received_multi_parcel", "not_received", [...delivery(twoParcels), order(), policy("shipping")]),
  shape(
    "not_received_in_transit",
    "not_received",
    delivery({ carrier: "Northwind Express", proofType: "in_transit", trackingNumber: "TRK9", trackingUrl: "https://example.test/t/TRK9" }, "supporting"),
  ),
  shape("credit_not_processed", "credit_not_processed", [noReturn(), comms(), order(), policy("refund")]),
  shape("not_as_described", "not_as_described", [
    fact("manual_evidence", "product_description", "Product listing", "supporting", { collected: true }),
    ...delivery(),
    order(),
    policy("refund"),
  ]),
  shape("subscription", "subscription", [history(), comms(), order(), policy("refund"), fact("subscription_terms", "subscription_terms", "Subscription terms", "strong", {})]),
  shape("never_cited", "adverse", [
    // address-match-only verification: not citable (lib/argument/paymentVerification.ts)
    fact("payment_authentication", "avs_cvv_match", "Payment authentication", "moderate", { network: "mastercard", avsResultCode: "Y" }, { bankEligible: false }),
    // CANCEL screening, different-country IP, AVS mismatch: submission risk, kept internal
    fact("fraud_screening", "fraud_risk_screening", "Pre-authorization fraud screening", "moderate", { recommendation: "CANCEL" }, { submissionRisk: true, includeInBankNarrative: false }),
    fact("ip_location", "ip_location_check", "IP & location consistency", "moderate", { locationMatch: "different_country" }, { submissionRisk: true, includeInBankNarrative: false }),
    fact("payment_authentication", "avs_cvv_match", "Payment authentication", "strong", { network: "visa", avsResultCode: "N", cvvResultCode: "M" }, { submissionRisk: true, includeInBankNarrative: false }),
    // the one fact that may be cited
    ...delivery(),
    order(),
  ]),
];
